INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Standing_Cable_Wood_Chop', 'Standing Cable Wood Chop', 'core', ARRAY['shoulders']::text[], 'cable', 'strength', 'beginner', 'Connect a standard handle to a tower, and move the cable to the highest pulley position. With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable. With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extend'),
('Standing_Calf_Raises', 'Standing Calf Raises', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Adjust the padded lever of the calf raise machine to fit your height. Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be fa'),
('Standing_Concentration_Curl', 'Standing Concentration Curl', 'arms', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Taking a dumbbell in your working hand, lean forward. Allow your working arm to hang perpendicular to the ground with the elbow pointing out. This will be your starting position. Flex the elbow to curl the weight, keeping the upper arm stationary. At the top of the repetition, flex the biceps and pause. Lower the dumbbell back to the starting position. Repeat the movement for the prescribed amount of repetitions.'),
('Standing_Dumbbell_Calf_Raise', 'Standing Dumbbell Calf Raise', 'legs', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'Stand with your torso upright holding two dumbbells in your hands by your sides. Place the ball of the foot on a sturdy and stable wooden board (that is around 2-3 inches tall) while your heels extend off and touch the floor. This will be your starting position. With the toes pointing either straight (to hit all parts equally), inwards (for emphasis on the outer head) or outwards (for emphasis on the inner head), raise the heels off the floor as you exhale by contracting the calves. Hold the top'),
('Standing_Dumbbell_Press', 'Standing Dumbbell Press', 'shoulders', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Standing with your feet shoulder width apart, take a dumbbell in each hand. Raise the dumbbells to head height, the elbows out and about 90 degrees. This will be your starting position. Maintaining strict technique with no leg drive or leaning back, extend through the elbow to raise the weights together directly above your head. Pause, and slowly return the weight to the starting position.'),
('Standing_Dumbbell_Reverse_Curl', 'Standing Dumbbell Reverse Curl', 'arms', ARRAY['arms']::text[], 'dumbbell', 'strength', 'intermediate', 'To begin, stand straight with a dumbbell in each hand using a pronated grip (palms facing down). Your arms should be fully extended while your feet are shoulder width apart from each other. This is the starting position. While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a seco'),
('Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head', 'Standing Dumbbell Straight-Arm Front Delt Raise Above Head', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'Hold the dumbbells in front of your thighs, palms facing your thighs. Keep your arms straight with a slight bend at the elbows but keep them locked. This will be your starting position. Raise the dumbbells in a semicircular motion to arm''s length overhead as you exhale. Slowly return to the starting position using the same path as you inhale. Repeat for the recommended amount of repetitions.'),
('Standing_Dumbbell_Triceps_Extension', 'Standing Dumbbell Triceps Extension', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'To begin, stand up with a dumbbell held by both hands. Your feet should be about shoulder width apart from each other. Slowly use both hands to grab the dumbbell and lift it over your head until both arms are fully extended. The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hands should be facing up towards the ceiling. This will be your starting position. Keeping your upper arms close to your head with elbows in and perpendicular to the floo'),
('Standing_Dumbbell_Upright_Row', 'Standing Dumbbell Upright Row', 'back', ARRAY['arms','shoulders']::text[], 'dumbbell', 'strength', 'beginner', 'Grasp a dumbbell in each hand with a pronated (palms forward) grip that is slightly less than shoulder width. The dumbbells should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position. Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be close to the body as you move it up and the elbows should drive the motion. Continue to lift them until they nearly t'),
('Standing_Elevated_Quad_Stretch', 'Standing Elevated Quad Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Start by standing with your back about two to three feet away from a bench or step. Lift one leg behind you and rest your foot on the step,either on your instep or the ball of your foot, whichever you find most comfortable. Keep your supporting knee slightly bent and avoid letting that knee extend out beyond your toes. Switch sides.'),
('Standing_Front_Barbell_Raise_Over_Head', 'Standing Front Barbell Raise Over Head', 'shoulders', ARRAY[]::text[], 'barbell', 'strength', 'intermediate', 'To begin, stand straight with a barbell in your hands. You should grip the bar with palms facing down and a closer than shoulder width grip apart from each other. Your feet should be shoulder width apart from each other. Your elbows should be slightly bent. This is the starting position. Lift the barbell up until it is directly over your head while exhaling. Make sure to keep your elbows slightly bent when performing each repetition. Once you feel the contraction, begin to lower the barbell back'),
('Standing_Gastrocnemius_Calf_Stretch', 'Standing Gastrocnemius Calf Stretch', 'legs', ARRAY['legs']::text[], 'other', 'stretching', 'beginner', 'Place your right heel on a step with your knee extended and lean forward to grab your right toe with your right hand. Your left knee should be slightly bent and your back should be straight. Support your weight on your left leg and place your left hand on your left thigh. Pull your right toes toward your knee until you feel a stretch in your calf.'),
('Standing_Hamstring_and_Calf_Stretch', 'Standing Hamstring and Calf Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Being by looping a belt, band, or rope around one foot. While standing, place that foot forward. Bend your back leg, while keeping the front one straight. Now raise the toes of your front foot off of the ground and lean forward. Using the belt, pull on the top of the foot to increase the stretch in the calf. Hold for 10-20 seconds and repeat with the other foot.'),
('Standing_Hip_Circles', 'Standing Hip Circles', 'legs', ARRAY['legs']::text[], 'bodyweight', 'stretching', 'beginner', 'Begin standing on one leg, holding to a vertical support. Raise the unsupported knee to 90 degrees. This will be your starting position. Open the hip as far as possible, attempting to make a big circle with your knee. Perform this movement slowly for a number of repetitions, and repeat on the other side.'),
('Standing_Hip_Flexors', 'Standing Hip Flexors', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Stand up straight with the spine vertical, the left foot slightly in front of the right. Bend both knees and lift the back heel off the floor as you press the right hip forward. You can''t get a thorough, deep stretch in this position, however, because it''s hard to relax the hip flexor and stand on it at the same time. Switch sides.'),
('Standing_Inner-Biceps_Curl', 'Standing Inner-Biceps Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'Stand up with a dumbbell in each hand being held at arms length. The elbows should be close to the torso. Your legs should be at about shoulder''s width apart from each other. Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position. While holding the upper arms stationary, curl the weights out while contracting the biceps as you breathe out. Your wrist should turn so that when the weights are fully elevated you have supinated grip ('),
('Standing_Lateral_Stretch', 'Standing Lateral Stretch', 'core', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Take a slightly wider than hip distance stance with your knees slightly bent. Place your right hand on your right hip to support the spine. Raise your left arm in a vertical line and place your left hand behind your head. Keep it there as you incline your torso to the right. Keep your weight evenly distributed between both legs (don''t lean into your left hip). Switch sides.'),
('Standing_Leg_Curl', 'Standing Leg Curl', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad. Keeping the torso bent forward, ensure your leg is fully stretched and grab the side handles of the machine. Position your toes straight. This will be your'),
('Standing_Long_Jump', 'Standing Long Jump', 'legs', ARRAY['legs','legs','legs']::text[], 'bodyweight', 'plyometrics', 'beginner', 'This drill is best done in sand or other soft landing surface. Ensure that you are able to measure distance. Stand in a partial squat stance with feet shoulder width apart. Utilizing a big arm swing and a countermovement of the legs, jump forward as far as you can. Attempt to land with your feet out in front you, reaching as far as possible with your legs. Measure the distance from your landing point to the starting point and track results.'),
('Standing_Low-Pulley_Deltoid_Raise', 'Standing Low-Pulley Deltoid Raise', 'shoulders', ARRAY['arms']::text[], 'cable', 'strength', 'beginner', 'Start by standing to the right side of a low pulley row. Use your left hand to come across the body and grab a single handle attached to the low pulley with a pronated grip (palms facing down). Rest your arm in front of you. Your right hand should grab the machine for better support and balance. Make sure that your back is erect and your feet are shoulder width apart from each other. This is the starting position. Begin to use the left hand and come across your body out until it is elevated to s'),
('Standing_Low-Pulley_One-Arm_Triceps_Extension', 'Standing Low-Pulley One-Arm Triceps Extension', 'arms', ARRAY['chest','shoulders']::text[], 'cable', 'strength', 'intermediate', 'Grab a single handle with your left arm next to the low pulley machine. Turn away from the machine keeping the handle to the side of your body with your arm fully extended. Now use both hands to elevate the single handle directly above the head with the palm facing forward. Keep your upper arm completely vertical (perpendicular to the floor) and put your right hand on your left elbow to help keep it steady. This is the starting position. Keeping your upper arms close to your head (elbows in) and'),
('Standing_Military_Press', 'Standing Military Press', 'shoulders', ARRAY['arms']::text[], 'barbell', 'strength', 'beginner', 'Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other. Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other. Once you pick up the barbell with the correct grip length, l'),
('Standing_Olympic_Plate_Hand_Squeeze', 'Standing Olympic Plate Hand Squeeze', 'arms', ARRAY['arms']::text[], 'other', 'strength', 'beginner', 'To begin, stand straight while holding a weight plate by the ridge at arm''s length in each hand using a neutral grip (palms facing in). You feet should be shoulder width apart from each other. This will be your starting position. Lower the plates until the fingers are nearly extended but can still hold weights. Inhale as you lower the plates. Now raise the plates back to the starting position as you exhale by closing your hands. Repeat for the recommended amount of repetitions prescribed in you'),
('Standing_One-Arm_Cable_Curl', 'Standing One-Arm Cable Curl', 'arms', ARRAY[]::text[], 'cable', 'strength', 'intermediate', 'Start out by grabbing single handle next to the low pulley machine. Make sure you are far enough from the machine so that your arm is supporting the weight. Make sure that your upper arm is stationary, perpendicular to the floor with elbows in and palms facing forward. Your non lifting arm should be grabbing your waist. This will allow you to keep your balance. Slowly begin to curl the single handle upwards while keeping the upper arm stationary until your forearm touches your bicep while exhali'),
('Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench', 'Standing One-Arm Dumbbell Curl Over Incline Bench', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Stand on the back side of an incline bench as if you were going to be a spotter for someone. Have a dumbbell in one hand and rest it across the incline bench with a supinated (palms up) grip. Position your non lifting hand at the corner or side of the incline bench. The chest should be pressed against the top part of the incline and your feet should be pressed against the floor at a wide stance. This is the starting position. While holding the upper arm stationary, curl the dumbbell upward while'),
('Standing_One-Arm_Dumbbell_Triceps_Extension', 'Standing One-Arm Dumbbell Triceps Extension', 'arms', ARRAY['chest','shoulders']::text[], 'dumbbell', 'strength', 'beginner', 'To begin, stand up with a dumbbell held in one hand. Your feet should be about shoulder width apart from each other. Now fully extend the arm with the dumbbell over your head. Tip: The small finger of your hand should be facing the ceiling and the palm of your hand should be facing forward. The dumbbell should be above your head. This will be your starting position. Keeping your upper arm close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion'),
('Standing_Overhead_Barbell_Triceps_Extension', 'Standing Overhead Barbell Triceps Extension', 'arms', ARRAY['shoulders']::text[], 'barbell', 'strength', 'beginner', 'To begin, stand up holding a barbell or e-z bar using a pronated grip (palms facing forward) with your hands closer than shoulder width apart from each other. Your feet should be about shoulder width apart. Now elevate the barbell above your head until your arms are fully extended. Keep your elbows in. This will be your starting position. Keeping your upper arms close to your head and elbows in, perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your'),
('Standing_Palm-In_One-Arm_Dumbbell_Press', 'Standing Palm-In One-Arm Dumbbell Press', 'shoulders', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Start by having a dumbbell in one hand with your arm fully extended to the side using a neutral grip. Use your other arm to hold on to an incline bench to keep your balance. Your feet should be shoulder width apart from each other. Now slowly lift the dumbbell up until you create a 90 degree angle with your arm. Note: Your forearm should be perpendicular to the floor. Continue to maintain a neutral grip throughout the entire exercise. Slowly lift the dumbbell up until your arm is fully extended.'),
('Standing_Palms-In_Dumbbell_Press', 'Standing Palms-In Dumbbell Press', 'shoulders', ARRAY['arms']::text[], 'dumbbell', 'strength', 'intermediate', 'Start by having a dumbbell in each hand with your arm fully extended to the side using a neutral grip. Your feet should be shoulder width apart from each other. Now slowly lift the dumbbells up until you create a 90 degree angle with your arms. Note: Your forearms should be perpendicular to the floor. This the starting position. Continue to maintain a neutral grip throughout the entire exercise. Slowly lift the dumbbells up until your arms are fully extended. While inhaling lower the weights dow'),
('Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl', 'Standing Palms-Up Barbell Behind The Back Wrist Curl', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Start by standing straight and holding a barbell behind your glutes at arm''s length while using a pronated grip (palms will be facing back away from the glutes) and having your hands shoulder width apart from each other. You should be looking straight forward while your feet are shoulder width apart from each other. This is the starting position. While exhaling, slowly elevate the barbell up by curling your wrist in a semi-circular motion towards the ceiling. Note: Your wrist should be the only'),
('Standing_Pelvic_Tilt', 'Standing Pelvic Tilt', 'back', ARRAY['legs']::text[], 'other', 'stretching', 'beginner', 'Start off with your feet hip-distance apart. Bend your knees slightly to keep them soft and springy. You may want to move your pelvis forward and backward and back few times before holding the tailbone forward in this stretch.'),
('Standing_Rope_Crunch', 'Standing Rope Crunch', 'core', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Attach a rope to a high pulley and select an appropriate weight. Stand with your back to the cable tower. Take the rope with both hands over your shoulders, holding it to your upper chest. This will be your starting position. Perform the movement by flexing the spine, crunching the weight down as far as you can. Hold the peak contraction for a moment before returning to the starting position.'),
('Standing_Soleus_And_Achilles_Stretch', 'Standing Soleus And Achilles Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Stand with your feet hip-distance apart, one foot slightly in front of the other. Bend both knees, keeping your back heel on the floor. Switch sides.'),
('Standing_Toe_Touches', 'Standing Toe Touches', 'legs', ARRAY['legs']::text[], 'other', 'stretching', 'beginner', 'Stand with some space in front and behind you. Bend at the waist, keeping your legs straight, until you can relax and let your upper body hang down in front of you. Let your arms and hands hang down naturally. Hold for 10 to 20 seconds.'),
('Standing_Towel_Triceps_Extension', 'Standing Towel Triceps Extension', 'arms', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'To begin, stand up with both arms fully extended above the head holding one end of a towel with both hands. Your elbows should be in and the arms perpendicular to the floor with the palms facing each other while your feet should be shoulder width apart from each other. This is the starting position. Now communicate with your partner so that he/she can grip the other side of the towel to apply resistance. Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower'),
('Standing_Two-Arm_Overhead_Throw', 'Standing Two-Arm Overhead Throw', 'shoulders', ARRAY['chest','back']::text[], 'other', 'plyometrics', 'beginner', 'Stand with your feet shoulder width apart holding a medicine ball in both hands. To begin, reach the medicine ball deep behind your head as you bend the knees slightly and lean back. Violently throw the ball forward, flexing at the hip and using your whole body to complete the movement. The medicine ball can be thrown to a partner or to a wall, receiving it as it bounces back.'),
('Star_Jump', 'Star Jump', 'legs', ARRAY['legs','legs','legs','shoulders']::text[], 'bodyweight', 'plyometrics', 'beginner', 'Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body. To initiate the move, squat down halfway and explode back up as high as possible. Fully extend your entire body, spreading your legs and arms away from the body. As you land, bring your limbs back in and absorb your impact through the legs.'),
('Step-up_with_Knee_Raise', 'Step-up with Knee Raise', 'legs', ARRAY['legs','legs']::text[], 'bodyweight', 'strength', 'beginner', 'Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position. Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can. Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg.'),
('Step_Mill', 'Step Mill', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'cardio', 'intermediate', 'To begin, step onto the stepmill and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Use caution so that you don''t trip as you climb the stairs. It is recommended that you maintain your grip on the handles so that you don''t fall. Stepmills offer convenience, cardiovascular benefits, and usually have less impact than running outsid'),
('Stiff-Legged_Barbell_Deadlift', 'Stiff-Legged Barbell Deadlift', 'legs', ARRAY['legs','back']::text[], 'barbell', 'strength', 'intermediate', 'Grasp a bar using an overhand grip (palms facing down). You may need some wrist wraps if using a significant amount of weight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position. Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the hips while keeping your back straight. Keep moving forward as if you were going to pick something from the floor unt'),
('Stiff-Legged_Dumbbell_Deadlift', 'Stiff-Legged Dumbbell Deadlift', 'legs', ARRAY['legs','back']::text[], 'dumbbell', 'strength', 'beginner', 'Grasp a couple of dumbbells holding them by your side at arm''s length. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position. Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as y'),
('Stiff_Leg_Barbell_Good_Morning', 'Stiff Leg Barbell Good Morning', 'back', ARRAY['legs','legs']::text[], 'barbell', 'strength', 'beginner', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a s'),
('Stomach_Vacuum', 'Stomach Vacuum', 'core', ARRAY[]::text[], 'bodyweight', 'stretching', 'beginner', 'To begin, stand straight with your feet shoulder width apart from each other. Place your hands on your hips. This is the starting position. Now slowly inhale as much air as possible and then start to exhale as much as possible while bringing your stomach in as much as possible and hold this position. Try to visualize your navel touching your backbone. One isometric contraction is around 20 seconds. During the 20 second hold, try to breathe normally. Then inhale and bring your stomach back to the'),
('Straight-Arm_Dumbbell_Pullover', 'Straight-Arm Dumbbell Pullover', 'chest', ARRAY['back','shoulders','arms']::text[], 'dumbbell', 'strength', 'intermediate', 'Place a dumbbell standing up on a flat bench. Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well. Grasp the dumbbell with both hands and hold it straight over your chest at arms length. Both palms should be pressing against the underside one of'),
('Straight-Arm_Pulldown', 'Straight-Arm Pulldown', 'back', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip. Step backwards two feet or so. Bend your torso forward at the waist by around 30-degrees with your arms fully extended in front of you and a slight bend at the elbows. If your arms are not fully extended then you need to step a bit more backwards until they are. Once your arms are fully extended and your torso is slightly bent at the waist, tighten t'),
('Straight_Bar_Bench_Mid_Rows', 'Straight Bar Bench Mid Rows', 'back', ARRAY['arms','back']::text[], 'barbell', 'strength', 'beginner', 'Place a loaded barbell on the end of a bench. Standing on the bench behind the bar, take a medium, pronated grip. Stand with your hips back and chest up, maintaining a neutral spine. This will be your starting position. Row the bar to your torso by retracting the shoulder blades and flexing the elbows. Use a controlled movement with no jerking. After a brief pause, slowly return the bar to the starting position, ensuring to go all the way down.'),
('Straight_Raises_on_Incline_Bench', 'Straight Raises on Incline Bench', 'shoulders', ARRAY['back']::text[], 'barbell', 'strength', 'beginner', 'Place a bar on the ground behind the head of an incline bench. Lay on the bench face down. With a pronated grip, pick the barbell up from the floor, keeping your arms straight. Allow the bar to hang straight down. This will be your starting position. To begin, raise the barbell out in front of your head while keeping your arms extended. Return to the starting position.'),
('Stride_Jump_Crossover', 'Stride Jump Crossover', 'legs', ARRAY['legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Stand to the side of a box with your inside foot on top of it, close to the edge. Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward. Land in the opposite position that you started, on the opposite side of the box. The foot that was initially on the box will now be on the ground, with the opposite foot now on the box. Repeat the movement, crossing back over to the other side.'),
('Sumo_Deadlift', 'Sumo Deadlift', 'legs', ARRAY['legs','arms','legs','back','back','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms. Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, sprea'),
('Sumo_Deadlift_with_Bands', 'Sumo Deadlift with Bands', 'legs', ARRAY['legs','arms','legs','back','back','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. Ensure that they under the back half of your foot, directly where you are driving into the floor. Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a ')
